import type { MaskitoOptions } from "@maskito/core";
import { maskitoTransform } from "@maskito/core";
import type { MaskitoDateParams } from "@maskito/kit";
import { maskitoDate, maskitoStringifyDate, maskitoWithPlaceholder } from "@maskito/kit";
import { useMemo } from "react";
import typeHelper from "@/lib/type-helper";
import { makeStableMaskitoOptions, type StableMaskitoOptions } from "./stable-mask";

const PLACEHOLDER_BY_MODE = {
  "dd/mm/yyyy": "__/__/____",
  "mm/yyyy": "__/____",
  yyyy: "____",
} as const;

export type DateMaskMode = keyof typeof PLACEHOLDER_BY_MODE;

export function dateMaskRemover(
  value: string | null | undefined,
  mode: DateMaskMode = "dd/mm/yyyy",
): string {
  if (!value?.length) return "";

  const trimmed = value.trim();

  if (mode === "yyyy") {
    const match = trimmed.match(/^(\d{4})$/);
    if (!match) return "";
    return match[1];
  }

  if (mode === "mm/yyyy") {
    const match = trimmed.match(/^(\d{2})\/(\d{4})$/);
    if (!match) return "";
    const [, mm, yyyy] = match;
    return `${yyyy}-${mm}`;
  }

  const match = trimmed.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (!match) return "";
  const [, dd, mm, yyyy] = match;
  return `${yyyy}-${mm}-${dd}`;
}

type DateMaskOptionsProps = Partial<Pick<MaskitoDateParams, "min" | "max">> & {
  mode?: DateMaskMode;
};

const defaultOptions = {
  mode: "dd/mm/yyyy",
  separator: "/",
} satisfies Partial<MaskitoDateParams>;

export const createDateMaskOptions: (options?: DateMaskOptionsProps) => MaskitoOptions = (
  options,
) => {
  const mode: DateMaskMode = options?.mode ?? "dd/mm/yyyy";
  const validOptions: MaskitoDateParams = {
    ...defaultOptions,
    ...options,
    mode,
  };
  const generatedOptions = maskitoDate(validOptions);
  const { plugins: datePlaceholderPlugins, ...datePlaceholderOptions } = maskitoWithPlaceholder(
    PLACEHOLDER_BY_MODE[mode],
    true,
  );

  return {
    ...generatedOptions,
    plugins: [...datePlaceholderPlugins, ...(generatedOptions.plugins ?? [])],
    preprocessors: [
      ...datePlaceholderOptions.preprocessors,
      ...(generatedOptions.preprocessors ?? []),
    ],
    postprocessors: [
      ...(generatedOptions.postprocessors ?? []),
      ...datePlaceholderOptions.postprocessors,
    ],
  };
};

export function useCreateDateMaskOptions(options?: DateMaskOptionsProps): StableMaskitoOptions {
  return useMemo(() => makeStableMaskitoOptions(createDateMaskOptions(options)), [options]);
}

export function dateMaskFormatter(
  value: string | Date | null | undefined,
  options?: DateMaskOptionsProps,
): string {
  const mode: DateMaskMode = options?.mode ?? "dd/mm/yyyy";
  const narrowOptions: DateMaskOptionsProps = { ...options, mode };

  switch (true) {
    case typeHelper.isString(value):
      return maskitoTransform(value, createDateMaskOptions(narrowOptions));

    case typeHelper.isDate(value):
      return maskitoStringifyDate(value, {
        ...defaultOptions,
        ...narrowOptions,
      });

    default:
      return "";
  }
}

// `dateMaskRemover`'s output is an ISO-ish string ("yyyy-mm-dd", "yyyy-mm",
// or "yyyy" depending on mode). `new Date(iso)` parses date-only ISO
// strings as UTC, which can shift by a day once rendered in local time —
// split and construct locally instead.
export function parseIsoDateParts(iso: string): Date | undefined {
  if (!iso) return undefined;
  const [yyyy, mm, dd] = iso.split("-").map(Number);
  if (Number.isNaN(yyyy)) return undefined;
  return new Date(yyyy, (mm || 1) - 1, dd || 1);
}

import type { MaskitoOptions } from "@maskito/core";
import { maskitoTransform } from "@maskito/core";
import type { MaskitoDateMode, MaskitoDateParams } from "@maskito/kit";
import { maskitoDateRange, maskitoStringifyDate, maskitoWithPlaceholder } from "@maskito/kit";
import { useMemo } from "react";
import { type DateMaskMode, dateMaskRemover, parseIsoDateParts } from "./date-mask";
import { makeStableMaskitoOptions, type StableMaskitoOptions } from "./stable-mask";

// Structurally identical to react-day-picker's `DateRange` type, so values
// from either type are assignable to the other — kept local to avoid a
// react-day-picker dependency for standalone (non-calendar) mask usage.
export type DateRangeValue = {
  from: Date | undefined;
  to?: Date | undefined;
};

export function dateRangeMaskRemover(value: string | null | undefined): string {
  return value?.replace(/[^\d-]/g, "").replace(/--/g, "-") || "";
}

type DateRangeMaskOptionsProps = {
  mode?: MaskitoDateMode;
  dateSeparator?: string;
};

const defaultOptions: { mode: MaskitoDateMode; dateSeparator?: string } = {
  mode: "dd/mm/yyyy",
  dateSeparator: "/",
};

const RANGE_SEPARATOR = " – ";

// Only the 3 modes this design system's date pickers actually use get a
// correctly-shaped placeholder; any other MaskitoDateMode (e.g. the
// American "mm/dd/yyyy") falls back to the original fixed dd/mm/yyyy-shaped
// placeholder, preserving this function's pre-existing behavior for modes
// nothing here exercises.
const RANGE_SEGMENT_PLACEHOLDER: Partial<Record<MaskitoDateMode, string>> = {
  "dd/mm/yyyy": "__/__/____",
  "mm/yyyy": "__/____",
  yyyy: "____",
};
const DEFAULT_RANGE_SEGMENT_PLACEHOLDER = "__/__/____";

export const createDateRangeMaskOptions: (options?: DateRangeMaskOptionsProps) => MaskitoOptions = (
  options,
) => {
  const validOptions: { mode: MaskitoDateMode; dateSeparator?: string } = {
    ...defaultOptions,
    ...options,
  };
  const generatedOptions = maskitoDateRange(validOptions);

  const segmentPlaceholder =
    RANGE_SEGMENT_PLACEHOLDER[validOptions.mode] ?? DEFAULT_RANGE_SEGMENT_PLACEHOLDER;
  const fullPlaceholder = `${segmentPlaceholder}${RANGE_SEPARATOR}${segmentPlaceholder}`;
  const { plugins: drPlaceholderPlugins, ...drPlaceholderOptions } = maskitoWithPlaceholder(
    fullPlaceholder,
    true,
  );

  return {
    ...generatedOptions,
    plugins: [...drPlaceholderPlugins, ...(generatedOptions.plugins ?? [])],
    preprocessors: [
      ...drPlaceholderOptions.preprocessors,
      ...(generatedOptions.preprocessors ?? []),
    ],
    postprocessors: [
      ...(generatedOptions.postprocessors ?? []),
      ...drPlaceholderOptions.postprocessors,
    ],
  };
};

export function useCreateDateRangeMaskOptions(
  options?: DateRangeMaskOptionsProps,
): StableMaskitoOptions {
  return useMemo(() => makeStableMaskitoOptions(createDateRangeMaskOptions(options)), [options]);
}

type DateRangeMaskFormatterInput = string | { from?: Date; to?: Date } | null | undefined;

export function dateRangeMaskFormatter(
  value: DateRangeMaskFormatterInput,
  options?: DateRangeMaskOptionsProps,
): string {
  if (!value) return "";

  if (typeof value === "string") {
    if (!value.length) return "";
    return maskitoTransform(value, createDateRangeMaskOptions(options));
  }

  const { from, to } = value;
  if (!from) return "";

  const stringifyOptions: MaskitoDateParams = {
    mode: options?.mode ?? defaultOptions.mode,
    separator: options?.dateSeparator ?? defaultOptions.dateSeparator ?? "/",
  };
  const fromStr = maskitoStringifyDate(from, stringifyOptions);
  if (!to) return fromStr;
  const toStr = maskitoStringifyDate(to, stringifyOptions);
  return `${fromStr}${RANGE_SEPARATOR}${toStr}`;
}

// Matches each "date segment" in a masked range value directly (rather than
// round-tripping through dateRangeMaskRemover's flattened digit string),
// then delegates each half to dateMaskRemover — same ISO conversion logic
// the single-date mask already uses, no duplication.
const SEGMENT_PATTERN_BY_MODE: Record<DateMaskMode, string> = {
  "dd/mm/yyyy": String.raw`\d{2}\/\d{2}\/\d{4}`,
  "mm/yyyy": String.raw`\d{2}\/\d{4}`,
  yyyy: String.raw`\d{4}`,
};

export function dateRangeMaskParser(
  value: string | null | undefined,
  mode: DateMaskMode = "dd/mm/yyyy",
): { from: string; to: string } {
  if (!value) return { from: "", to: "" };

  const segment = SEGMENT_PATTERN_BY_MODE[mode];

  const fullMatch = value.match(new RegExp(`^(${segment}).*?(${segment})$`));
  if (fullMatch) {
    const [, fromRaw, toRaw] = fullMatch;
    return {
      from: dateMaskRemover(fromRaw, mode),
      to: dateMaskRemover(toRaw, mode),
    };
  }

  // `dateRangeMaskFormatter` emits a bare single segment (no separator) for
  // a from-only range — e.g. the calendar's onSelect firing after the first
  // click of a new selection. Without this branch, that clean single-segment
  // value fails the two-segment match above and silently collapses to
  // `{from: "", to: ""}`, dropping the just-picked `from` on its next
  // render.
  const fromOnlyMatch = value.match(new RegExp(`^(${segment})$`));
  if (fromOnlyMatch) {
    return { from: dateMaskRemover(fromOnlyMatch[1], mode), to: "" };
  }

  return { from: "", to: "" };
}

export function parseIsoDateRangeParts(parts: {
  from: string;
  to: string;
}): DateRangeValue | undefined {
  const from = parseIsoDateParts(parts.from);
  if (!from) return undefined;
  const to = parseIsoDateParts(parts.to);
  return { from, to };
}

import type { MaskitoOptions } from "@maskito/core";
import { maskitoTransform } from "@maskito/core";
import type { MaskitoDateTimeParams } from "@maskito/kit";
import {
  maskitoDateTime,
  maskitoParseDateTime,
  maskitoStringifyDateTime,
  maskitoWithPlaceholder,
} from "@maskito/kit";
import { useMemo } from "react";
import { makeStableMaskitoOptions, type StableMaskitoOptions } from "./stable-mask";

export function dateTimeMaskRemover(value: string | null | undefined): string {
  if (!value?.length) return "";

  const trimmed = value.trim();

  // maskitoParseDateTime requires both date and time parts;
  // preprend default time if missing
  const needsTimePad = !trimmed.includes(",");
  const normalized = needsTimePad ? `${trimmed}, 00:00` : trimmed;

  const parsed = maskitoParseDateTime(normalized, defaultOptions);

  if (!parsed) return "";

  return parsed.toISOString();
}

type DateTimeMaskOptionsProps = Partial<
  Pick<MaskitoDateTimeParams, "dateMode" | "timeMode" | "dateSeparator">
>;

const defaultOptions: MaskitoDateTimeParams = {
  dateMode: "dd/mm/yyyy",
  timeMode: "HH:MM",
  dateSeparator: "/",
};

const DATE_TIME_PLACEHOLDER = "__/__/____, __:__";

const { plugins: dtPlaceholderPlugins, ...dtPlaceholderOptions } = maskitoWithPlaceholder(
  DATE_TIME_PLACEHOLDER,
  true,
);

export const createDateTimeMaskOptions: (options?: DateTimeMaskOptionsProps) => MaskitoOptions = (
  options,
) => {
  const validOptions = { ...defaultOptions, ...options };
  const generatedOptions = maskitoDateTime(validOptions);

  return {
    ...generatedOptions,
    plugins: [...dtPlaceholderPlugins, ...(generatedOptions.plugins ?? [])],
    preprocessors: [
      ...dtPlaceholderOptions.preprocessors,
      ...(generatedOptions.preprocessors ?? []),
    ],
    postprocessors: [
      ...(generatedOptions.postprocessors ?? []),
      ...dtPlaceholderOptions.postprocessors,
    ],
  };
};

export function useCreateDateTimeMaskOptions(
  options?: DateTimeMaskOptionsProps,
): StableMaskitoOptions {
  return useMemo(() => makeStableMaskitoOptions(createDateTimeMaskOptions(options)), [options]);
}

export function dateTimeMaskFormatter(
  value: string | Date | null | undefined,
  options?: DateTimeMaskOptionsProps,
): string {
  const validOptions = { ...defaultOptions, ...options };

  if (value instanceof Date) {
    return maskitoStringifyDateTime(value, validOptions);
  }

  if (!value?.length) return "";

  return maskitoTransform(value, createDateTimeMaskOptions(validOptions));
}

import type { MaskitoOptions } from "@maskito/core";
import { maskitoTransform } from "@maskito/core";
import type { MaskitoNumberParams } from "@maskito/kit";
import { maskitoNumber, maskitoStringifyNumber } from "@maskito/kit";
import { useMemo } from "react";
import { makeStableMaskitoOptions, type StableMaskitoOptions } from "./stable-mask";

export function decimalMaskRemover(value: string | null | undefined): string {
  return value?.replace(/[^\d,]/g, "").replace(",", ".") || "";
}

type DecimalMaskOptionsProps = Partial<
  Pick<
    MaskitoNumberParams,
    "min" | "max" | "minimumFractionDigits" | "maximumFractionDigits" | "prefix" | "postfix"
  >
>;

const defaultOptions: MaskitoNumberParams = {
  decimalSeparator: ",",
  thousandSeparator: ".",
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
};

export const createDecimalMaskOptions: (options?: DecimalMaskOptionsProps) => MaskitoOptions = (
  options,
) => {
  const validOptions = { ...defaultOptions, ...options };

  return maskitoNumber(validOptions);
};

export function useCreateDecimalMaskOptions(
  options?: DecimalMaskOptionsProps,
): StableMaskitoOptions {
  return useMemo(() => makeStableMaskitoOptions(createDecimalMaskOptions(options)), [options]);
}

export function decimalMaskFormatter(
  value: string | number | null | undefined,
  options?: DecimalMaskOptionsProps,
): string {
  const validOptions = { ...defaultOptions, ...options };

  switch (typeof value) {
    case "string":
      return maskitoTransform(value, createDecimalMaskOptions(validOptions));

    case "number":
    case "bigint":
      return maskitoStringifyNumber(value, validOptions);

    default:
      return "";
  }
}

