import type { MaskitoMaskExpression, MaskitoOptions, MaskitoPostprocessor } from "@maskito/core";
import { maskitoWithPlaceholder } from "@maskito/kit";

/**
 * Shared factory for fixed-pattern masks (CPF, CNPJ, CEP, credit card, …):
 * combines a mask expression with a typed placeholder and optional extra
 * postprocessors. Internal helper — each mask module keeps its own public
 * `create*MaskOptions` / `use*` / remover / formatter API.
 */
export function createPatternMaskOptions(
  pattern: MaskitoMaskExpression,
  placeholder: string,
  extraPostprocessors: MaskitoPostprocessor[] = [],
): MaskitoOptions {
  const { plugins, ...placeholderRest } = maskitoWithPlaceholder(placeholder, true);

  return {
    mask: pattern,
    plugins: [...plugins],
    preprocessors: [...placeholderRest.preprocessors],
    postprocessors: [...placeholderRest.postprocessors, ...extraPostprocessors],
  };
}

import type { MaskitoMaskExpression, MaskitoOptions } from "@maskito/core";
import { maskitoTransform, maskitoUpdateElement } from "@maskito/core";
import { maskitoEventHandler, maskitoWithPlaceholder } from "@maskito/kit";
import { useMemo } from "react";
import { makeStableMaskitoOptions, type StableMaskitoOptions } from "./stable-mask";

const FIXED_PHONE_PLACEHOLDER = "(__) ____-____";
const MOBILE_PHONE_PLACEHOLDER = "(__) _____-____";

const { removePlaceholder: removeFixedPlaceholder } = maskitoWithPlaceholder(
  FIXED_PHONE_PLACEHOLDER,
  true,
);

const { removePlaceholder: removeMobilePlaceholder } = maskitoWithPlaceholder(
  MOBILE_PHONE_PLACEHOLDER,
  true,
);

function resolvePhoneDisplay(value: string): {
  placeholder: string;
  remover: (value: string) => string;
} {
  const numericValue = phoneMaskRemover(value);
  const isMobile = numericValue.charAt(2) === "9";
  return isMobile
    ? {
        placeholder: MOBILE_PHONE_PLACEHOLDER,
        remover: removeMobilePlaceholder,
      }
    : { placeholder: FIXED_PHONE_PLACEHOLDER, remover: removeFixedPlaceholder };
}

function isPhoneMobile(value: string): boolean {
  const numericValue = phoneMaskRemover(value);
  return numericValue.charAt(2) === "9";
}

function fillPhonePlaceholder(value: string): string {
  const numericValue = phoneMaskRemover(value);
  const isMobile = isPhoneMobile(value) || numericValue.length >= 11;
  const placeholder = isMobile ? MOBILE_PHONE_PLACEHOLDER : FIXED_PHONE_PLACEHOLDER;

  let result = "";
  let digitIndex = 0;
  for (const char of placeholder) {
    if (char === "_") {
      result += digitIndex < numericValue.length ? numericValue[digitIndex] : "_";
      digitIndex++;
    } else {
      result += char;
    }
  }
  return result;
}

const fixePhoneMaskPattern: MaskitoMaskExpression = [
  "(",
  /\d/,
  /\d/,
  ")",
  " ",
  /\d/,
  /\d/,
  /\d/,
  /\d/,
  "-",
  /\d/,
  /\d/,
  /\d/,
  /\d/,
];

const mobilePhoneMaskPattern: MaskitoMaskExpression = [
  "(",
  /\d/,
  /\d/,
  ")",
  " ",
  /\d/,
  /\d/,
  /\d/,
  /\d/,
  /\d/,
  "-",
  /\d/,
  /\d/,
  /\d/,
  /\d/,
];

export function phoneMaskRemover(value: string) {
  return value.replace(/\D/g, "");
}

function _createPhoneMaskOptions(): MaskitoOptions {
  let phoneIsFocused = false;

  return {
    mask: ({ value }) => {
      const numericValue = phoneMaskRemover(value);
      const isMobile = numericValue.charAt(2) === "9";
      return isMobile ? mobilePhoneMaskPattern : fixePhoneMaskPattern;
    },
    plugins: [
      maskitoEventHandler("focus", (element) => {
        phoneIsFocused = true;
        maskitoUpdateElement(element, fillPhonePlaceholder(element.value));
      }),
      maskitoEventHandler("blur", (element) => {
        phoneIsFocused = false;
        const { remover } = resolvePhoneDisplay(element.value);
        maskitoUpdateElement(element, remover(element.value));
      }),
    ],
    preprocessors: [
      ({ elementState, data }) => {
        if (!phoneIsFocused) return { elementState, data };

        return {
          elementState: {
            ...elementState,
            value: fillPhonePlaceholder(elementState.value),
          },
          data,
        };
      },
    ],
    postprocessors: [
      (elementState) => {
        if (!phoneIsFocused) return elementState;

        return {
          ...elementState,
          value: fillPhonePlaceholder(elementState.value),
        };
      },
    ],
  };
}

export const createPhoneMaskOptions = _createPhoneMaskOptions;

export function phoneMaskFormatter(input: string) {
  if (!input?.length) return "";
  return maskitoTransform(input, createPhoneMaskOptions());
}

export function useCreatePhoneMaskOptions(): StableMaskitoOptions {
  return useMemo(() => makeStableMaskitoOptions(createPhoneMaskOptions()), []);
}

import { maskitoTransform } from "@maskito/core";
import type * as React from "react";
import { createCepMaskOptions } from "./cep-mask";
import { cnpjMaskRemover, createCnpjMaskOptions } from "./cnpj-mask";
import { createCnpjOrCpfMaskOptions } from "./cnpj-or-cpf-mask";
import { cpfMaskRemover, createCpfMaskOptions } from "./cpf-mask";
import { createCreditCardMaskOptions } from "./credit-card-mask";
import {
  createDateMaskOptions,
  dateMaskFormatter,
  dateMaskRemover,
  parseIsoDateParts,
} from "./date-mask";
import { createDateRangeMaskOptions, dateRangeMaskRemover } from "./date-range-mask";
import {
  createDateTimeMaskOptions,
  dateTimeMaskFormatter,
  dateTimeMaskRemover,
} from "./date-time-mask";
import { createDecimalMaskOptions, decimalMaskFormatter, decimalMaskRemover } from "./decimal-mask";
import { createPhoneMaskOptions, phoneMaskRemover } from "./phone-mask";
import { makeStableMaskitoOptions, type StableMaskitoOptions } from "./stable-mask";
import { createTimeMaskOptions, timeMaskRemover } from "./time-mask";

type DateParams = NonNullable<Parameters<typeof createDateMaskOptions>[0]>;
type TimeParams = NonNullable<Parameters<typeof createTimeMaskOptions>[0]>;
type DateTimeParams = NonNullable<Parameters<typeof createDateTimeMaskOptions>[0]>;
type DateRangeParams = NonNullable<Parameters<typeof createDateRangeMaskOptions>[0]>;
type DecimalParams = NonNullable<Parameters<typeof createDecimalMaskOptions>[0]>;

/** Masks that take no parameters. */
export type MaskPresetName =
  | "cpf"
  | "cnpj"
  | "cpf-cnpj"
  | "cep"
  | "phone"
  | "credit-card"
  | "date"
  | "time"
  | "date-time"
  | "date-range"
  | "decimal";

/** A preset by name, or a parameterized preset as `{ type, ...params }`. */
export type MaskSpec =
  | MaskPresetName
  | ({ type: "date" } & DateParams)
  | ({ type: "time" } & TimeParams)
  | ({ type: "date-time" } & DateTimeParams)
  | ({ type: "date-range" } & DateRangeParams)
  | ({ type: "decimal" } & DecimalParams);

/**
 * Everything an input needs to apply a mask: the Maskito options, the
 * conversions between the masked text and the raw value, and input hints.
 *
 * Raw values per preset: digits for documents, CEP, phone, credit card and
 * date ranges; ISO for date ("yyyy-mm-dd", "yyyy-mm" or "yyyy") and date-time;
 * "HH:MM" for time; a dot-decimal string ("1234.50") for decimal. Incomplete
 * dates and date-times have an empty raw value.
 */
export type ResolvedMask = {
  options: StableMaskitoOptions;
  /** Masked text → raw value. */
  unmask: (masked: string) => string;
  /** Raw (or already masked) value → masked text. */
  format: (raw: string) => string;
  inputMode?: React.HTMLAttributes<HTMLInputElement>["inputMode"];
  autoComplete?: string;
  placeholder?: string;
};

const digits = (value: string) => value.replace(/\D/g, "");

function transformWith(options: StableMaskitoOptions) {
  return (raw: string) => (raw ? maskitoTransform(raw, options) : "");
}

// "dd/mm/yyyy" → "dd/mm/aaaa": placeholders follow the pt-BR masks.
const datePlaceholder = (mode: string, separator = "/") =>
  mode.replace("yyyy", "aaaa").replaceAll("/", separator);

function resolveDigits(
  options: StableMaskitoOptions,
  hints: Pick<ResolvedMask, "inputMode" | "autoComplete" | "placeholder">,
  unmask: (masked: string) => string = digits,
): ResolvedMask {
  return { options, unmask, format: transformWith(options), ...hints };
}

function resolvePreset(spec: MaskSpec): ResolvedMask {
  const { type, ...params } = typeof spec === "string" ? { type: spec } : spec;
  const stable = makeStableMaskitoOptions;

  switch (type) {
    case "cpf":
      return resolveDigits(
        stable(createCpfMaskOptions()),
        { inputMode: "numeric", placeholder: "000.000.000-00" },
        cpfMaskRemover,
      );
    case "cnpj":
      return resolveDigits(
        stable(createCnpjMaskOptions()),
        { inputMode: "numeric", placeholder: "00.000.000/0000-00" },
        cnpjMaskRemover,
      );
    case "cpf-cnpj":
      return resolveDigits(stable(createCnpjOrCpfMaskOptions()), { inputMode: "numeric" });
    case "cep":
      return resolveDigits(stable(createCepMaskOptions()), {
        inputMode: "numeric",
        autoComplete: "postal-code",
        placeholder: "00000-000",
      });
    case "phone":
      return resolveDigits(
        stable(createPhoneMaskOptions()),
        { inputMode: "tel", autoComplete: "tel", placeholder: "(00) 00000-0000" },
        phoneMaskRemover,
      );
    case "credit-card":
      return resolveDigits(stable(createCreditCardMaskOptions()), {
        inputMode: "numeric",
        autoComplete: "cc-number",
        placeholder: "0000 0000 0000 0000",
      });
    case "date": {
      const dateParams = params as DateParams;
      const mode = dateParams.mode ?? "dd/mm/yyyy";
      return {
        options: stable(createDateMaskOptions(dateParams)),
        unmask: (masked) => dateMaskRemover(masked, mode),
        format: (raw) => {
          const date = /^\d{4}(-\d{2}){0,2}$/.test(raw) ? parseIsoDateParts(raw) : undefined;
          return date ? dateMaskFormatter(date, dateParams) : dateMaskFormatter(raw, dateParams);
        },
        inputMode: "numeric",
        placeholder: datePlaceholder(mode),
      };
    }
    case "time": {
      const timeParams = params as TimeParams;
      const options = stable(createTimeMaskOptions(timeParams));
      return {
        options,
        unmask: timeMaskRemover,
        format: transformWith(options),
        inputMode: "numeric",
        placeholder: (timeParams.mode ?? "HH:MM").toLowerCase(),
      };
    }
    case "date-time": {
      const dateTimeParams = params as DateTimeParams;
      const dateMode = dateTimeParams.dateMode ?? "dd/mm/yyyy";
      const timeMode = dateTimeParams.timeMode ?? "HH:MM";
      return {
        options: stable(createDateTimeMaskOptions(dateTimeParams)),
        unmask: dateTimeMaskRemover,
        format: (raw) => {
          const date = /^\d{4}-\d{2}-\d{2}T/.test(raw) ? new Date(raw) : undefined;
          return dateTimeMaskFormatter(date ?? raw, dateTimeParams);
        },
        inputMode: "numeric",
        placeholder: `${datePlaceholder(dateMode, dateTimeParams.dateSeparator)}, ${timeMode.toLowerCase()}`,
      };
    }
    case "date-range": {
      const rangeParams = params as DateRangeParams;
      const placeholder = datePlaceholder(
        rangeParams.mode ?? "dd/mm/yyyy",
        rangeParams.dateSeparator,
      );
      const options = stable(createDateRangeMaskOptions(rangeParams));
      return {
        options,
        unmask: (masked) => digits(dateRangeMaskRemover(masked)),
        format: transformWith(options),
        inputMode: "numeric",
        placeholder: `${placeholder} – ${placeholder}`,
      };
    }
    case "decimal": {
      const decimalParams = params as DecimalParams;
      return {
        options: stable(createDecimalMaskOptions(decimalParams)),
        unmask: decimalMaskRemover,
        format: (raw) => {
          if (!raw) return "";
          const number = Number(raw);
          return Number.isNaN(number)
            ? decimalMaskFormatter(raw, decimalParams)
            : decimalMaskFormatter(number, decimalParams);
        },
        inputMode: "decimal",
        placeholder: decimalMaskFormatter(0, decimalParams),
      };
    }
  }
}

/**
 * Resolves a mask preset, or wraps custom Maskito options (whose raw value is
 * the masked text itself, since there is no generic way to unmask it).
 * Creates fresh options on every call: call it once per input (`useMask` does).
 */
export function resolveMask(mask: MaskSpec | StableMaskitoOptions): ResolvedMask {
  if (typeof mask === "string" || "type" in mask) return resolvePreset(mask);
  return { options: mask, unmask: (masked) => masked, format: transformWith(mask) };
}

import type { MaskitoOptions } from "@maskito/core";

import type { Brand } from "@/lib/types";

export type StableMaskitoOptions = Brand<MaskitoOptions, "StableMaskitoOptions">;

export function makeStableMaskitoOptions(options: MaskitoOptions): StableMaskitoOptions {
  return options as StableMaskitoOptions;
}

import type { MaskitoOptions } from "@maskito/core";
import type { MaskitoTimeParams } from "@maskito/kit";
import {
  maskitoParseTime,
  maskitoStringifyTime,
  maskitoTime,
  maskitoWithPlaceholder,
} from "@maskito/kit";
import { useMemo } from "react";
import { makeStableMaskitoOptions, type StableMaskitoOptions } from "./stable-mask";

export function timeMaskRemover(value: string | null | undefined): string {
  return value?.replace(/[^\d:]/g, "") || "";
}

type TimeMaskOptionsProps = Partial<Pick<MaskitoTimeParams, "mode">>;

const defaultOptions: MaskitoTimeParams = {
  mode: "HH:MM",
};

const TIME_PLACEHOLDER = "__:__";

const { plugins: timePlaceholderPlugins, ...timePlaceholderOptions } = maskitoWithPlaceholder(
  TIME_PLACEHOLDER,
  true,
);

export const createTimeMaskOptions: (options?: TimeMaskOptionsProps) => MaskitoOptions = (
  options,
) => {
  const validOptions = { ...defaultOptions, ...options };
  const generatedOptions = maskitoTime(validOptions);

  return {
    ...generatedOptions,
    plugins: [...timePlaceholderPlugins, ...(generatedOptions.plugins ?? [])],
    preprocessors: [
      ...timePlaceholderOptions.preprocessors,
      ...(generatedOptions.preprocessors ?? []),
    ],
    postprocessors: [
      ...(generatedOptions.postprocessors ?? []),
      ...timePlaceholderOptions.postprocessors,
    ],
  };
};

export function timeMaskFormatter(
  value: string | number | null | undefined,
  options?: TimeMaskOptionsProps,
): string {
  const validOptions = { ...defaultOptions, ...options };

  if (typeof value === "number") {
    return maskitoStringifyTime(value, validOptions);
  }

  if (value?.length) {
    const num = maskitoParseTime(value, validOptions);
    return maskitoStringifyTime(num, validOptions);
  }

  return "";
}

export function useCreateTimeMaskOptions(options?: TimeMaskOptionsProps): StableMaskitoOptions {
  return useMemo(() => makeStableMaskitoOptions(createTimeMaskOptions(options)), [options]);
}
